using System;
using FiveDo.Core;

namespace FiveDo.Video;

/// <summary>
/// The CPU reference implementation of the HQx 2x/3x/4x pixel-art filters.
/// </summary>
/// <remarks>
/// <para>
/// The rules are derived from Maxim Stepin's hq2x/hq3x/hq4x (Copyright (C) 2003
/// Maxim Stepin, maxst@hiend3d.com) and Cameron Zemek's C port (Copyright (C)
/// 2010 Cameron Zemek, grom@zeminvaders.net), both distributed under the GNU
/// Lesser General Public License 2.1 or later. The compact
/// <see cref="HqxRuleTable"/> is generated by <c>tools/generate_hqx_rules.py</c>
/// from the 4DO reference sources.
/// </para>
/// <para>
/// The accelerated presenters run the same rule table on the GPU. This class
/// remains the reference oracle for the C++ reference hashes and the opt-in GPU
/// parity tests. It consumes the CPU-expanded BGRA frame, so palette expansion
/// stays pixel-identical to <see cref="FrameAssembler"/>.
/// </para>
/// </remarks>
public sealed class HqxFilter
{
    /// <summary>The smallest HQx scale factor.</summary>
    public const int MinScale = 2;

    /// <summary>The largest HQx scale factor.</summary>
    public const int MaxScale = 4;

    private uint[] _source = [];
    private uint[] _destination = [];
    private readonly uint[] _window = new uint[10];

    /// <summary>Gets the scale factor used by a video filter, or 2 for non-HQx filters.</summary>
    /// <param name="filter">Video filter.</param>
    /// <returns>The HQx scale factor.</returns>
    public static int ScaleFor(VideoFilter filter)
    {
        return filter switch
        {
            VideoFilter.Hqx3x => 3,
            VideoFilter.Hqx4x => 4,
            _ => 2,
        };
    }

    /// <summary>Expands a BGRA frame by 2x, 3x, or 4x.</summary>
    /// <param name="source">Source frame.</param>
    /// <param name="destination">Destination frame, which must be an integer multiple of the source size.</param>
    /// <exception cref="ArgumentNullException">Thrown when a frame is null.</exception>
    /// <exception cref="ArgumentException">Thrown when the destination size is not an HQx scale.</exception>
    public void Expand(FrameBuffer source, FrameBuffer destination)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(destination);
        if (source.Width <= 0 || source.Height <= 0
            || destination.Width % source.Width != 0)
        {
            throw new ArgumentException(
                $"The HQx destination must be {MinScale}x-{MaxScale}x the source size.",
                nameof(destination));
        }

        var scale = destination.Width / source.Width;
        if (scale is < MinScale or > MaxScale
            || destination.Height != source.Height * scale)
        {
            throw new ArgumentException(
                $"The HQx destination must be {MinScale}x-{MaxScale}x the source size.",
                nameof(destination));
        }

        var width = source.Width;
        var height = source.Height;
        var pixelCount = checked(width * height);
        if (_source.Length < pixelCount)
        {
            _source = new uint[pixelCount];
            _destination = new uint[checked(pixelCount * MaxScale * MaxScale)];
        }

        ToArgb(source.PixelSpan, pixelCount, _source);
        var sourcePixels = _source;
        var destinationPixels = _destination;
        var w = _window;
        for (var y = 0; y < height; y++)
        {
            var previous = y > 0 ? -width : 0;
            var next = y < height - 1 ? width : 0;
            for (var x = 0; x < width; x++)
            {
                w[2] = sourcePixels[(y * width) + previous + x];
                w[5] = sourcePixels[(y * width) + x];
                w[8] = sourcePixels[(y * width) + next + x];

                if (x > 0)
                {
                    w[1] = sourcePixels[(y * width) + previous + x - 1];
                    w[4] = sourcePixels[(y * width) + x - 1];
                    w[7] = sourcePixels[(y * width) + next + x - 1];
                }
                else
                {
                    w[1] = w[2];
                    w[4] = w[5];
                    w[7] = w[8];
                }

                if (x < width - 1)
                {
                    w[3] = sourcePixels[(y * width) + previous + x + 1];
                    w[6] = sourcePixels[(y * width) + x + 1];
                    w[9] = sourcePixels[(y * width) + next + x + 1];
                }
                else
                {
                    w[3] = w[2];
                    w[6] = w[5];
                    w[9] = w[8];
                }

                var pattern = ComputePattern(w);
                var condition0 = Diff(w[2], w[4]);
                var condition1 = Diff(w[2], w[6]);
                var condition2 = Diff(w[4], w[8]);
                var condition3 = Diff(w[6], w[8]);
                var destinationRow = y * scale;
                var destinationColumn = x * scale;
                var ruleRowOffset = HqxRuleTable.RowOffset(scale);
                for (var row = 0; row < scale; row++)
                {
                    var destinationOffset = ((destinationRow + row) * width * scale) + destinationColumn;
                    for (var column = 0; column < scale; column++)
                    {
                        var subpixel = (row * scale) + column;
                        var ruleOffset = (((ruleRowOffset + subpixel) * HqxRuleTable.PatternCount) + pattern) * 2;
                        var rule = HqxRuleTable.Rules[ruleOffset];
                        var condition = (int)((rule >> 27) & 7);
                        if (condition != 7)
                        {
                            var selected = condition switch
                            {
                                0 => condition0,
                                1 => condition1,
                                2 => condition2,
                                _ => condition3,
                            };
                            if (selected)
                            {
                                rule = HqxRuleTable.Rules[ruleOffset + 1];
                            }
                        }

                        destinationPixels[destinationOffset + column] = ApplyRule(rule, w);
                    }
                }
            }
        }

        ToBgra(destinationPixels, destination.PixelSpan, pixelCount * scale * scale);
    }

    private static uint ApplyRule(uint rule, uint[] w)
    {
        var weight0 = (int)(rule & 0xF);
        var index0 = (int)((rule >> 4) & 0xF);
        var weight1 = (int)((rule >> 8) & 0xF);
        var index1 = (int)((rule >> 12) & 0xF);
        var weight2 = (int)((rule >> 16) & 0xF);
        var index2 = (int)((rule >> 20) & 0xF);
        var shift = (int)((rule >> 24) & 0x7);

        var color0 = w[index0 + 1];
        var color1 = w[index1 + 1];
        var color2 = w[index2 + 1];

        var r = ((((color0 >> 16) & 0xFF) * weight0)
            + (((color1 >> 16) & 0xFF) * weight1)
            + (((color2 >> 16) & 0xFF) * weight2)) >> shift;
        var g = ((((color0 >> 8) & 0xFF) * weight0)
            + (((color1 >> 8) & 0xFF) * weight1)
            + (((color2 >> 8) & 0xFF) * weight2)) >> shift;
        var b = (((color0 & 0xFF) * weight0)
            + ((color1 & 0xFF) * weight1)
            + ((color2 & 0xFF) * weight2)) >> shift;
        return 0xFF000000u | ((uint)r << 16) | ((uint)g << 8) | (uint)b;
    }

    private static int ComputePattern(uint[] w)
    {
        var (centerY, centerU, centerV) = ToYuv(w[5]);
        var pattern = 0;
        var flag = 1;
        for (var i = 1; i <= 9; i++)
        {
            if (i == 5)
            {
                continue;
            }

            if (w[i] != w[5])
            {
                var (y, u, v) = ToYuv(w[i]);
                if (Math.Abs(centerY - y) > 48 || Math.Abs(centerU - u) > 7 || Math.Abs(centerV - v) > 6)
                {
                    pattern |= flag;
                }
            }

            flag <<= 1;
        }

        return pattern;
    }

    private static bool Diff(uint c1, uint c2)
    {
        var (y1, u1, v1) = ToYuv(c1);
        var (y2, u2, v2) = ToYuv(c2);
        return Math.Abs(y1 - y2) > 48 || Math.Abs(u1 - u2) > 7 || Math.Abs(v1 - v2) > 6;
    }

    private static uint Interp1(uint c1, uint c2)
    {
        return Interpolate2(c1, 3, c2, 1, 2);
    }

    private static uint Interp2(uint c1, uint c2, uint c3)
    {
        return Interpolate3(c1, 2, c2, 1, c3, 1, 2);
    }

    private static uint Interp3(uint c1, uint c2)
    {
        return Interpolate2(c1, 7, c2, 1, 3);
    }

    private static uint Interp4(uint c1, uint c2, uint c3)
    {
        return Interpolate3(c1, 2, c2, 7, c3, 7, 4);
    }

    private static uint Interp5(uint c1, uint c2)
    {
        return Interpolate2(c1, 1, c2, 1, 1);
    }

    private static uint Interp6(uint c1, uint c2, uint c3)
    {
        return Interpolate3(c1, 5, c2, 2, c3, 1, 3);
    }

    private static uint Interp7(uint c1, uint c2, uint c3)
    {
        return Interpolate3(c1, 6, c2, 1, c3, 1, 3);
    }

    private static uint Interp8(uint c1, uint c2)
    {
        return Interpolate2(c1, 5, c2, 3, 3);
    }

    private static uint Interp9(uint c1, uint c2, uint c3)
    {
        return Interpolate3(c1, 2, c2, 3, c3, 3, 3);
    }

    private static uint Interp10(uint c1, uint c2, uint c3)
    {
        return Interpolate3(c1, 14, c2, 1, c3, 1, 4);
    }

    private static uint Interpolate2(uint c1, uint w1, uint c2, uint w2, int shift)
    {
        if (c1 == c2)
        {
            return c1;
        }

        unchecked
        {
            return ((((((c1 & 0xFF000000u) >> 24) * w1) + (((c2 & 0xFF000000u) >> 24) * w2)) << (24 - shift)) & 0xFF000000u)
                + (((((c1 & 0x0000FF00u) * w1) + ((c2 & 0x0000FF00u) * w2)) >> shift) & 0x0000FF00u)
                + (((((c1 & 0x00FF00FFu) * w1) + ((c2 & 0x00FF00FFu) * w2)) >> shift) & 0x00FF00FFu);
        }
    }

    private static uint Interpolate3(uint c1, uint w1, uint c2, uint w2, uint c3, uint w3, int shift)
    {
        unchecked
        {
            return ((((((c1 & 0xFF000000u) >> 24) * w1) + (((c2 & 0xFF000000u) >> 24) * w2) + (((c3 & 0xFF000000u) >> 24) * w3)) << (24 - shift)) & 0xFF000000u)
                + (((((c1 & 0x0000FF00u) * w1) + ((c2 & 0x0000FF00u) * w2) + ((c3 & 0x0000FF00u) * w3)) >> shift) & 0x0000FF00u)
                + (((((c1 & 0x00FF00FFu) * w1) + ((c2 & 0x00FF00FFu) * w2) + ((c3 & 0x00FF00FFu) * w3)) >> shift) & 0x00FF00FFu);
        }
    }

    private static (int Y, int U, int V) ToYuv(uint color)
    {
        var r = (int)((color >> 16) & 0xFF);
        var g = (int)((color >> 8) & 0xFF);
        var b = (int)(color & 0xFF);
        var y = (int)((0.299 * r) + (0.587 * g) + (0.114 * b));
        var u = ((int)((-0.169 * r) - (0.331 * g) + (0.5 * b)) + 128) & 0xFF;
        var v = ((int)((0.5 * r) - (0.419 * g) - (0.081 * b)) + 128) & 0xFF;
        return (y, u, v);
    }

    private static void ToArgb(ReadOnlySpan<byte> source, int pixelCount, uint[] destination)
    {
        var offset = 0;
        for (var i = 0; i < pixelCount; i++)
        {
            destination[i] = 0xFF000000u
                | ((uint)source[offset + 2] << 16)
                | ((uint)source[offset + 1] << 8)
                | source[offset];
            offset += 4;
        }
    }

    private static void ToBgra(ReadOnlySpan<uint> source, Span<byte> destination, int pixelCount)
    {
        var offset = 0;
        for (var i = 0; i < pixelCount; i++)
        {
            var color = source[i];
            destination[offset] = (byte)color;
            destination[offset + 1] = (byte)(color >> 8);
            destination[offset + 2] = (byte)(color >> 16);
            destination[offset + 3] = 0xFF;
            offset += 4;
        }
    }
}
